@Singleton
public class LiveLogClient
{
	private static final String DEFAULT_API_URL = "https://api.runelogs.com";
	private static final long LOGOUT_SESSION_GAP_MS = 15 * 60 * 1000L;
	/** Stop an automatically started live log after this long away from leaderboard content while logged in (~10 min). */
	private static final long AUTO_LIVE_LOG_STOP_DELAY_MS = 10 * 60 * 1000L;
	/** Stop an automatically started live log after this long logged out, regardless of where you were (~5 min). */
	private static final long AUTO_LIVE_LOG_LOGGED_OUT_STOP_DELAY_MS = 5 * 60 * 1000L;
	/** Game ticks between batch flushes (~2.4s at 0.6s/tick). */
	private static final int FLUSH_INTERVAL_TICKS = 4;
	/** Game ticks between heartbeats while idle (~30s at 0.6s/tick). */
	private static final int HEARTBEAT_INTERVAL_TICKS = 50;
	/** Disable live logging after batch failures spanning this many ticks (~60s). */
	private static final int BATCH_FAILURE_DISABLE_TICKS = 100;
	private static final int MAX_LINES_PER_REQUEST = 2000;
	private static final int MAX_PENDING_LINES = 100_000;

	private final CombatLoggerConfig config;
	private final Client client;
	private final ClientThread clientThread;
	private final ChatMessageManager chatMessageManager;
	private final HttpClient httpClient;
	// Created in startUp() and terminated in shutDown(). The plugin is a @Singleton, so a
	// disable/enable cycle reuses this instance; recreating here keeps every send from throwing
	// RejectedExecutionException on a terminated pool. volatile because startUp/shutDown and sends
	// run on different threads.
	private volatile ExecutorService executor;
	private final Object pendingLock = new Object();
	private final Deque<String> pendingLines = new ArrayDeque<>();

	private volatile boolean enabled;
	// True when the current session was started automatically (leaderboard content auto-logging)
	// rather than manually by the user. Used so auto-stop never kills a manually started session,
	// and so the log page is not auto-opened for automatically started sessions.
	private volatile boolean autoStarted;
	private volatile String currentLogId;
	private Supplier<List<String>> initialMessageSupplier = List::of;
	private int lastFlushTick = -1;
	private int lastHeartbeatTick = -1;
	private int batchFailureStartTick = -1;
	private int pendingLineCount = 0;
	// True while a start/batch HTTP request is outstanding. Blocks new flushes so lines
	// stay at the front of pendingLines until the server acks them, preserving send order.
	private boolean inFlight;
	// Set when entering the login screen; used to decide whether logging out continues
	// the current live session or starts a new one.
	private Instant loggedOutAt;
	// Sends a "start" command on the next flush instead of appending to the current log.
	private boolean needsNewSession;
	// Auto live logging (leaderboard content): last time the player was in a leaderboard region, and
	// whether they were in one on the previous tick (so we only auto-start on first entering it).
	private Instant lastLeaderboardRegionAt;
	private boolean wasInLeaderboardContent;

	@Inject
	private LiveLogClient(
			CombatLoggerConfig config,
			Client client,
			ClientThread clientThread,
			ChatMessageManager chatMessageManager)
	{
		this.config = config;
		this.client = client;
		this.clientThread = clientThread;
		this.chatMessageManager = chatMessageManager;
		this.httpClient = HttpClient.newBuilder()
				.connectTimeout(Duration.ofSeconds(10))
				.build();
	}

	public void startUp()
	{
		if (executor == null || executor.isShutdown())
		{
			executor = Executors.newSingleThreadExecutor();
		}
	}

	public void shutDown()
	{
		if (enabled && currentLogId != null)
		{
			sendCommandAsync("stop", List.of(), false, 0, true, currentLogId);
		}
		disableLiveLogging(null, false, false, false);
		if (executor != null)
		{
			executor.shutdownNow();
		}
	}

	public boolean isEnabled()
	{
		return enabled;
	}

	public boolean isAutoStarted()
	{
		return enabled && autoStarted;
	}

	public String getCurrentLogId()
	{
		return currentLogId;
	}

	public void setInitialMessageSupplier(Supplier<List<String>> initialMessageSupplier)
	{
		this.initialMessageSupplier = initialMessageSupplier != null ? initialMessageSupplier : List::of;
	}

	public void setEnabled(boolean enabled)
	{
		if (this.enabled == enabled)
		{
			return;
		}

		if (!enabled)
		{
			if (currentLogId != null)
			{
				sendCommandAsync("stop", List.of(), false, 0, true, currentLogId);
			}
			disableLiveLogging(null, false, false, false);
			sendLiveLogChatMessage("Runelogs live logging disabled.");
			return;
		}

		if (!config.allowLiveLogging())
		{
			showErrorDialog(
					"Live logging is not allowed.\n\n"
							+ "Enable \"Allow Live Logging\" in the Combat Logger plugin settings under Runelogs.");
			return;
		}

		if (!hasAccessKey())
		{
			showErrorDialog(
					"You need a Runelogs access key to use live logging.\n\n"
							+ "Generate one at runelogs.com/live-log and add it in the Combat Logger plugin settings.");
			return;
		}

		this.enabled = true;
		this.autoStarted = false;
		needsNewSession = true;
		batchFailureStartTick = -1;
		loggedOutAt = null;
		lastFlushTick = client.getTickCount();
		lastHeartbeatTick = client.getTickCount();
		sendLiveLogChatMessage("Runelogs live logging enabled.");
	}

	/**
	 * Starts live logging automatically (e.g. on entering leaderboard content).
	 * Unlike {@link #setEnabled(boolean)}, this never shows a popup dialog when live logging is not
	 * allowed or no access key is configured - it just silently does nothing. Does nothing if live
	 * logging is already enabled, so it never overrides a manual session.
	 */
	public void startAutomatic()
	{
		if (enabled || !canUseRunelogsLiveLogging())
		{
			return;
		}

		this.enabled = true;
		this.autoStarted = true;
		needsNewSession = true;
		batchFailureStartTick = -1;
		loggedOutAt = null;
		lastFlushTick = client.getTickCount();
		lastHeartbeatTick = client.getTickCount();
		sendLiveLogChatMessage("Runelogs live logging automatically started.");
	}

	/**
	 * Stops an automatically started live log. Does nothing if live logging is disabled or if the
	 * current session was started manually, so a user's manual live log is never stopped.
	 */
	public void stopAutomatic()
	{
		if (!enabled || !autoStarted)
		{
			return;
		}

		if (currentLogId != null)
		{
			sendCommandAsync("stop", List.of(), false, 0, true, currentLogId);
		}
		disableLiveLogging(null, false, false, false);
		sendLiveLogChatMessage("Runelogs live logging automatically stopped.");
	}

	/**
	 * Automatically starts live logging when the player is in a leaderboard-content region, and stops
	 * an automatically started log once the player has been away from any such region for 10 minutes.
	 * A manually started live log is never stopped here, and no log page is opened automatically.
	 * Stopping while logged out is handled separately by {@link #checkLoggedOutAutoStop()}.
	 */
	private void checkAutoLiveLogging()
	{
		if (!config.autoLiveLogLeaderboardContent())
		{
			// Feature is off: stop any log it started, but leave a manually started one running.
			if (isAutoStarted())
			{
				stopAutomatic();
			}
			lastLeaderboardRegionAt = null;
			wasInLeaderboardContent = false;
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		LocalPoint localPoint = local.getLocalLocation();
		int regionId = localPoint == null ? -1 : WorldPoint.fromLocalInstance(client, localPoint).getRegionID();
		if (regionId < 0)
		{
			// Region unknown (e.g. mid-loading) - keep current state instead of treating it as leaving content.
			return;
		}

		boolean inLeaderboardContent = LeaderboardRegions.isLeaderboardRegion(regionId);

		if (inLeaderboardContent)
		{
			lastLeaderboardRegionAt = Instant.now();

			// Only auto-start when first entering leaderboard content, so a session the user manually
			// stopped while still inside the content is not immediately restarted.
			if (!wasInLeaderboardContent && !enabled)
			{
				startAutomatic();
			}
		}
		else if (isAutoStarted() && lastLeaderboardRegionAt != null
				&& Duration.between(lastLeaderboardRegionAt, Instant.now()).toMillis() >= AUTO_LIVE_LOG_STOP_DELAY_MS)
		{
			stopAutomatic();
			lastLeaderboardRegionAt = null;
		}

		wasInLeaderboardContent = inLeaderboardContent;
	}

	/**
	 * Stops an automatically started live log once the player has been logged out for 5 minutes,
	 * regardless of where they were in game. Driven by client ticks (which keep firing on the login
	 * screen) so the session is finalized without needing the player to log back in. A manually
	 * started live log is never stopped here.
	 */
	private void checkLoggedOutAutoStop()
	{
		if (!enabled || !autoStarted || loggedOutAt == null)
		{
			return;
		}

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			return;
		}

		if (Duration.between(loggedOutAt, Instant.now()).toMillis() >= AUTO_LIVE_LOG_LOGGED_OUT_STOP_DELAY_MS)
		{
			stopAutomatic();
			// Reset leaderboard tracking so logging back in inside content starts a fresh auto session.
			lastLeaderboardRegionAt = null;
			wasInLeaderboardContent = false;
		}
	}

	/**
	 * Runs on every client tick (including while logged out) to drive the logged-out auto-stop.
	 */
	public void onClientTick()
	{
		checkLoggedOutAutoStop();
	}

	public void onGameStateChanged(GameState gameState)
	{
		if (!enabled)
		{
			return;
		}

		switch (gameState)
		{
			case LOGIN_SCREEN:
				if (loggedOutAt == null)
				{
					loggedOutAt = Instant.now();
				}
				break;
			case LOGGED_IN:
				if (loggedOutAt != null)
				{
					long logoutDurationMs = Duration.between(loggedOutAt, Instant.now()).toMillis();
					// World hop / brief disconnect: keep streaming to the same log.
					// Longer absence: treat it like a new play session.
					if (logoutDurationMs >= LOGOUT_SESSION_GAP_MS)
					{
						needsNewSession = true;
					}
					loggedOutAt = null;
				}
				break;
			default:
				break;
		}
	}

	public void onLineLogged(String formattedLine)
	{
		if (!enabled || formattedLine == null || formattedLine.isEmpty())
		{
			return;
		}

		if (!canUseRunelogsLiveLogging())
		{
			return;
		}

		synchronized (pendingLock)
		{
			if (pendingLineCount >= MAX_PENDING_LINES)
			{
				clientThread.invokeLater(this::disableForQueueOverflow);
				return;
			}

			pendingLines.addLast(formattedLine);
			pendingLineCount++;
		}
	}

	private void disableForQueueOverflow()
	{
		if (!enabled)
		{
			return;
		}

		disableLiveLogging(
				"Live logging was disabled because too many log lines were queued.\n\n"
						+ "This usually means Runelogs could not be reached for an extended period.",
				true,
				true,
				true);
	}

	public void onGameTick()
	{
		checkAutoLiveLogging();

		if (!enabled)
		{
			return;
		}

		if (!canUseRunelogsLiveLogging())
		{
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		int tick = client.getTickCount();
		if (tick - lastFlushTick >= FLUSH_INTERVAL_TICKS && hasPendingWork())
		{
			flushAsync();
			lastFlushTick = tick;
		}

		if (currentLogId != null && !needsNewSession && tick - lastHeartbeatTick >= HEARTBEAT_INTERVAL_TICKS)
		{
			// No combat lines to send, but the plugin is still enabled - ping the server
			// so it does not finalize the session during idle periods.
			sendCommandAsync("heartbeat", List.of(), false, 0, false, currentLogId);
			lastHeartbeatTick = tick;
		}
	}

	private boolean hasPendingWork()
	{
		synchronized (pendingLock)
		{
			return !inFlight && (!pendingLines.isEmpty() || needsNewSession);
		}
	}

	private List<String> snapshotPendingLines(int maxLines)
	{
		List<String> batch = new ArrayList<>();
		for (String line : pendingLines)
		{
			if (batch.size() >= maxLines)
			{
				break;
			}
			batch.add(line);
		}
		return batch;
	}

	private void removePendingLinesFromFront(int count)
	{
		for (int i = 0; i < count; i++)
		{
			pendingLines.pollFirst();
		}
		pendingLineCount -= count;
	}

	private boolean hasAccessKey()
	{
		String accessKey = config.runelogsAccessKey();
		return accessKey != null && !accessKey.trim().isEmpty();
	}

	private boolean canUseRunelogsLiveLogging()
	{
		return config.allowLiveLogging() && hasAccessKey();
	}

	private void flushAsync()
	{
		List<String> batch;
		boolean sendStart;
		int pendingLinesToAck;

		synchronized (pendingLock)
		{
			if (inFlight)
			{
				return;
			}

			sendStart = needsNewSession;
			if (!sendStart && currentLogId == null)
			{
				needsNewSession = true;
				sendStart = true;
			}

			if (!sendStart && pendingLines.isEmpty())
			{
				return;
			}

			batch = snapshotPendingLines(MAX_LINES_PER_REQUEST);
			pendingLinesToAck = batch.size();
			inFlight = true;
		}

		if (sendStart)
		{
			// "start" creates a new live log on the server and prepends initial messages.
			sendCommandAsync("start", buildSessionStartLines(batch), true, pendingLinesToAck, false, null);
			return;
		}

		sendCommandAsync("batch", batch, false, pendingLinesToAck, false, currentLogId);
	}

	private List<String> buildSessionStartLines(List<String> batch)
	{
		List<String> lines = new ArrayList<>();
		for (String message : initialMessageSupplier.get())
		{
			lines.add(buildFormattedLine(message));
		}
		lines.addAll(batch);
		return lines;
	}

	private String buildFormattedLine(String message)
	{
		return String.format("%s %s\t%s", client.getTickCount(), CombatLoggerPlugin.getCurrentTimestamp(), message);
	}

	private void sendCommandAsync(
			String command,
			List<String> lines,
			boolean isStart,
			int pendingLinesToAck,
			boolean blocking,
			String sessionLogId)
	{
		Runnable task = () -> sendCommand(command, lines, isStart, pendingLinesToAck, sessionLogId);
		if (blocking)
		{
			task.run();
			return;
		}

		try
		{
			executor.execute(task);
		}
		catch (RejectedExecutionException e)
		{
			// Executor was shut down (e.g. a disable/enable race). Release the in-flight guard so
			// the flush loop can recover on the next tick instead of buffering until overflow.
			clearInFlight();
		}
	}

	private void sendCommand(
			String command,
			List<String> lines,
			boolean isStart,
			int pendingLinesToAck,
			String sessionLogId)
	{
		if (!config.allowLiveLogging())
		{
			return;
		}

		if (!hasAccessKey())
		{
			if (isStart)
			{
				clientThread.invokeLater(() -> handleStartFailure(
						"You need a Runelogs access key to use live logging.\n\n"
								+ "Generate one at runelogs.com/live-log and add it in the Combat Logger plugin settings."));
			}
			else if ("batch".equals(command))
			{
				clientThread.invokeLater(this::handleBatchFailure);
			}
			return;
		}

		try
		{
			HttpRequest request = HttpRequest.newBuilder()
					.uri(URI.create(DEFAULT_API_URL + "/live-log/ingest"))
					.timeout(Duration.ofSeconds(15))
					.header("Authorization", "Bearer " + config.runelogsAccessKey().trim())
					.header("Content-Type", "application/json")
					.POST(HttpRequest.BodyPublishers.ofString(buildRequestBody(command, lines, sessionLogId)))
					.build();

			HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
			int statusCode = response.statusCode();
			if (statusCode >= 200 && statusCode < 300)
			{
				String body = response.body();
				clientThread.invokeLater(() -> handleSendSuccess(body, isStart, pendingLinesToAck));
			}
			else if (isStart)
			{
				clientThread.invokeLater(() -> handleStartFailure(
						"Could not connect to Runelogs (HTTP " + statusCode + ").\n\n"
								+ "Check your access key and try again."));
			}
			else if ("stop".equals(command) && (statusCode == 404 || statusCode == 409))
			{
				// Session already ended server-side.
			}
			else if (("batch".equals(command) || "heartbeat".equals(command))
					&& (statusCode == 404 || statusCode == 409))
			{
				clientThread.invokeLater(this::handleSessionInactive);
			}
			else if ("batch".equals(command))
			{
				clientThread.invokeLater(this::handleBatchFailure);
			}
			else if ("heartbeat".equals(command))
			{
				clientThread.invokeLater(this::handleBatchFailure);
			}
		}
		catch (Exception e)
		{
			if (isStart)
			{
				String detail = e.getMessage();
				if (detail == null || detail.isBlank())
				{
					detail = e.getClass().getSimpleName();
				}

				String failureMessage = "Could not connect to Runelogs.\n\n"
						+ detail + "\n\n"
						+ "Check your access key and try again.";
				clientThread.invokeLater(() -> handleStartFailure(failureMessage));
			}
			else if ("batch".equals(command))
			{
				clientThread.invokeLater(this::handleBatchFailure);
			}
		}
	}

	private void handleSendSuccess(String responseBody, boolean wasStart, int pendingLinesToAck)
	{
		if (!enabled)
		{
			clearInFlight();
			return;
		}

		currentLogId = extractJsonStringField(responseBody, "logId");
		lastHeartbeatTick = client.getTickCount();
		batchFailureStartTick = -1;

		if (wasStart && config.openLiveLogPageOnStart() && !autoStarted && currentLogId != null)
		{
			LinkBrowser.browse("https://runelogs.com/log/" + currentLogId);
		}

		synchronized (pendingLock)
		{
			if (pendingLinesToAck > 0)
			{
				removePendingLinesFromFront(pendingLinesToAck);
			}
			inFlight = false;
			if (wasStart)
			{
				needsNewSession = false;
			}
		}
	}

	private void handleSessionInactive()
	{
		if (!enabled)
		{
			clearInFlight();
			return;
		}

		synchronized (pendingLock)
		{
			currentLogId = null;
			needsNewSession = true;
			inFlight = false;
		}
	}

	private void handleBatchFailure()
	{
		if (!enabled)
		{
			clearInFlight();
			return;
		}

		synchronized (pendingLock)
		{
			inFlight = false;

			int tick = client.getTickCount();
			if (batchFailureStartTick < 0)
			{
				batchFailureStartTick = tick;
			}
			else if (tick - batchFailureStartTick >= BATCH_FAILURE_DISABLE_TICKS)
			{
				disableLiveLogging(
						"Could not connect to Runelogs for 60 seconds.\n\n"
								+ "Live logging has been disabled.",
						true,
						true,
						true);
			}
		}
	}

	private void clearInFlight()
	{
		synchronized (pendingLock)
		{
			inFlight = false;
		}
	}

	private void handleStartFailure(String message)
	{
		disableLiveLogging(message, true, true, false);
	}

	private void disableLiveLogging(String message, boolean showError, boolean notifyInChat, boolean sendStop)
	{
		boolean wasEnabled = enabled;
		if (wasEnabled && sendStop && currentLogId != null)
		{
			sendCommandAsync("stop", List.of(), false, 0, false, currentLogId);
		}

		enabled = false;
		autoStarted = false;
		currentLogId = null;
		needsNewSession = false;
		batchFailureStartTick = -1;
		loggedOutAt = null;

		synchronized (pendingLock)
		{
			pendingLines.clear();
			pendingLineCount = 0;
			inFlight = false;
		}

		if (message != null && (showError || notifyInChat))
		{
			sendLiveLogChatMessageMultiline(message);
		}
		else if (notifyInChat)
		{
			sendLiveLogChatMessage("Runelogs live logging disabled");
		}
	}

	private void showErrorDialog(String message)
	{
		clientThread.invokeLater(() -> JOptionPane.showMessageDialog(
				null,
				message,
				"Live Logging",
				JOptionPane.ERROR_MESSAGE));
	}

	private static String buildRequestBody(String command, List<String> lines, String logId)
	{
		StringBuilder sb = new StringBuilder();
		sb.append("{\"command\":\"").append(escapeJson(command)).append('"');
		if (logId != null)
		{
			sb.append(",\"logId\":\"").append(escapeJson(logId)).append('"');
		}
		sb.append(",\"lines\":[");
		boolean first = true;
		for (String line : lines)
		{
			if (!first)
			{
				sb.append(',');
			}
			sb.append('"').append(escapeJson(line)).append('"');
			first = false;
		}
		sb.append("]}");
		return sb.toString();
	}

	private static String escapeJson(String value)
	{
		return value
				.replace("\\", "\\\\")
				.replace("\"", "\\\"")
				.replace("\n", "\\n")
				.replace("\r", "\\r")
				.replace("\t", "\\t");
	}

	private static String extractJsonStringField(String json, String fieldName)
	{
		if (json == null)
		{
			return null;
		}

		String marker = "\"" + fieldName + "\":\"";
		int start = json.indexOf(marker);
		if (start < 0)
		{
			return null;
		}

		start += marker.length();
		int end = json.indexOf('"', start);
		if (end < 0)
		{
			return null;
		}

		return json.substring(start, end);
	}

	private void sendLiveLogChatMessage(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.GAMEMESSAGE)
				.runeLiteFormattedMessage(String.format("<col=cc0000>%s</col>", message))
				.build());
	}

	private void sendLiveLogChatMessageMultiline(String message)
	{
		for (String line : message.split("\n"))
		{
			line = line.trim();
			if (!line.isEmpty())
			{
				sendLiveLogChatMessage(line);
			}
		}
	}
}

package com.combatlogger;

import com.combatlogger.messages.DamageMessage;
import com.combatlogger.model.logs.*;
import com.combatlogger.util.HitSplatUtil;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import static com.combatlogger.CombatLoggerPlugin.LOG_FILE;
import static com.combatlogger.CombatLoggerPlugin.getCurrentTimestamp;

@Singleton
public class LogQueueManager
{
	private final Client client;
	private final Queue<Log> logQueue = new ConcurrentLinkedQueue<>();

	// File I/O runs on this single thread so it never blocks the client thread.
	private ExecutorService writeExecutor;
	// Only accessed from the writeExecutor thread.
	private BufferedWriter writer;
	private File writerFile;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private CombatLoggerConfig config;

	@Inject
	private PartyService party;

	@Inject
	private FightManager fightManager;

	@Inject
	private LiveLogClient liveLogClient;

	@Inject
	private LogQueueManager(Client client)
	{
		this.client = client;
	}

	public void startUp(EventBus eventBus)
	{
		writeExecutor = Executors.newSingleThreadExecutor(runnable -> {
			Thread thread = new Thread(runnable, "combat-logger-writer");
			thread.setDaemon(true);
			return thread;
		});
		eventBus.register(this);
	}

	public void shutDown(EventBus eventBus)
	{
		eventBus.unregister(this);
		// Let any queued writes finish, then release the file handle.
		writeExecutor.execute(this::closeWriter);
		writeExecutor.shutdown();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int currentTick = client.getTickCount();
		File logFile = LOG_FILE;
		List<String> linesToWrite = new ArrayList<>();

		// Wait until 2 ticks have passed before writing to the log file
		// So that we can enrich the data from other players in the Party with DamageMessage
		while (!logQueue.isEmpty() && currentTick >= logQueue.peek().getTickCount() + 2)
		{
			Log log = logQueue.poll();
			log(logFile, linesToWrite, log.getTickCount(), log.getTimestamp(), log.getMessage());

			if (log instanceof DamageLog && isNPC(((DamageLog) log).getTarget()))
			{
				fightManager.addDamage((DamageLog) log);
			}
			else if (log instanceof DeathLog && isNPC(((DeathLog) log).getTarget()))
			{
				fightManager.recordDeath((DeathLog) log);
			}
			else if (log instanceof TargetChangeLog && isNPC(((TargetChangeLog) log).getSource()) && !isNPC(((TargetChangeLog) log).getTarget()))
			{
				fightManager.recordNPCTargetingPlayer((TargetChangeLog) log);
			}
			else if (log instanceof GameMessageLog)
			{
				fightManager.handleGameMessage((GameMessageLog) log);
			}
			else if (log instanceof AttackAnimationLog && !isNPC(((AttackAnimationLog) log).getSource()))
			{
				fightManager.addTicks((AttackAnimationLog) log);
			}
			else if (log instanceof NpcChangedLog)
			{
				fightManager.handleNpcChanged((NpcChangedLog) log);
			}
		}

		if (!linesToWrite.isEmpty())
		{
			writeExecutor.execute(() -> writeLines(logFile, linesToWrite));
		}

		// No need to call panel.onGameTick(event); as FightManager handles game ticks.
	}

	private void log(File logFile, List<String> linesToWrite, int tickCount, String timestamp, String message)
	{
		String formattedLine = String.format("%s %s\t%s", tickCount, timestamp, message);
		if (logFile == null)
		{
			liveLogClient.onLineLogged(formattedLine);
			return;
		}

		linesToWrite.add(formattedLine);
		if (config.logInChat())
		{
			chatMessageManager
					.queue(QueuedMessage.builder()
							.type(ChatMessageType.GAMEMESSAGE)
							.sender("combat-logger")
							.runeLiteFormattedMessage(message.replace("\t", " "))
							.build());
		}

		liveLogClient.onLineLogged(formattedLine);
	}

	/**
	 * Runs on the writeExecutor thread. Keeps a single writer open across batches and only
	 * reopens it when the target log file changes (e.g. ::newlog or a new login).
	 */
	private void writeLines(File logFile, List<String> lines)
	{
		try
		{
			if (writer == null || !logFile.equals(writerFile))
			{
				closeWriter();
				writer = new BufferedWriter(new FileWriter(logFile, true));
				writerFile = logFile;
			}

			for (String line : lines)
			{
				writer.write(line);
				writer.write('\n');
			}
			writer.flush();
		}
		catch (IOException e)
		{
			e.printStackTrace();
			closeWriter();
		}
	}

	private void closeWriter()
	{
		if (writer == null)
		{
			return;
		}

		try
		{
			writer.close();
		}
		catch (IOException e)
		{
			e.printStackTrace();
		}
		finally
		{
			writer = null;
			writerFile = null;
		}
	}

	@Subscribe
	protected void onDamageMessage(DamageMessage event)
	{
		PartyMember localMember = party.getLocalMember();

		if (localMember == null || localMember.getMemberId() == event.getMemberId())
		{
			// Don't need to update logs from ourselves
			return;
		}

		PartyMember eventMember = party.getMemberById(event.getMemberId());
		String newHitsplatName = HitSplatUtil.replaceMeWithNewOther(event.getHitsplatName());

		// Find a matching damage log in the queue and then add the source of the damage and rename the hitsplat appropriately
		boolean matchFound = false;
		for (Log log : logQueue)
		{
			if (log instanceof DamageLog)
			{
				DamageLog damageLog = (DamageLog) log;
				if (damageLog.getSource().equals("Unknown")
						&& event.getDamage() == damageLog.getDamageAmount()
						&& event.getTarget().equals(damageLog.getTarget())
						&& HitSplatUtil.replaceMeWithExistingOther(event.getHitsplatName()).equals(damageLog.getHitsplatName()))
				{
					// Match found, update the existing damage log while preserving any tracked target health
					damageLog.setHitsplatName(newHitsplatName);
					damageLog.setSource(eventMember.getDisplayName());
					damageLog.setMessage(DamageLog.formatMessage(eventMember.getDisplayName(), newHitsplatName, event.getTarget(), event.getDamage(), damageLog.getTargetHealthRatio(), damageLog.getTargetHealthScale()));
					matchFound = true;
					break;
				}
			}
		}

		// If no match is found, add a new damage log to the queue
		if (!matchFound)
		{
			queue(
					new DamageLog(
							client.getTickCount(),
							getCurrentTimestamp(),
							String.format("%s\t%s\t%s\t%d", eventMember.getDisplayName(), newHitsplatName, event.getTarget(), event.getDamage()),
							eventMember.getDisplayName(),
							event.getTarget(),
							event.getTargetName(),
							event.getDamage(),
							newHitsplatName)
			);
		}
	}

	public void clearQueue()
	{
		logQueue.clear();
	}

	public void queue(Log log)
	{
		logQueue.add(log);
	}

	public void queue(String message)
	{
		logQueue.add(
				new Log(
						client.getTickCount(),
						getCurrentTimestamp(),
						message
				));
	}

	public static boolean isNPC(String name)
	{
		return name.matches("\\d+-\\d+");
	}
}

package com.combatlogger.encounters;

import com.combatlogger.LogQueueManager;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

@Singleton
public class ColosseumHelper
{
	/** No ScriptID gameval exists for the handicap selection script. */
	private static final int COLOSSEUM_MODIFIER_SELECTION_SCRIPT = 4931;
	private static final Pattern WAVE_START_PATTERN = Pattern.compile("Wave:\\s*(\\d+)", Pattern.CASE_INSENSITIVE);

	private enum ManticoreStyle
	{
		MAGE,
		RANGE,
		MELEE
	}

	private static final class ManticoreState
	{
		ManticoreStyle style;
		int attacksRemaining;
	}

	private final Client client;
	private final LogQueueManager logQueueManager;

	private final List<Integer> waveModifierOptions = new ArrayList<>(3);
	private final Map<Integer, ManticoreState> manticoresByIndex = new HashMap<>();
	private boolean inColosseum;

	@Inject
	ColosseumHelper(Client client, LogQueueManager logQueueManager)
	{
		this.client = client;
		this.logQueueManager = logQueueManager;
	}

	public void setInColosseum(boolean inColosseum)
	{
		if (this.inColosseum && !inColosseum)
		{
			reset();
		}
		this.inColosseum = inColosseum;
	}

	public void handleWaveStarted(String message)
	{
		if (!inColosseum || waveModifierOptions.isEmpty())
		{
			return;
		}

		Matcher matcher = WAVE_START_PATTERN.matcher(Text.removeTags(message));
		if (!matcher.find())
		{
			return;
		}

		logModifierChoice();
	}

	/**
	 * Manticore throw anim is shared across styles; styles are logged as specials instead.
	 */
	public boolean shouldSuppressAttackAnimation(NPC npc, int animationId)
	{
		return npc.getId() == NpcID.COLOSSEUM_MANTICORE
				&& animationId == AnimationID.NPC_MANTICORE_01_TRIPLE_THROW;
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (!inColosseum || event.getScriptId() != COLOSSEUM_MODIFIER_SELECTION_SCRIPT)
		{
			return;
		}

		waveModifierOptions.clear();
		Object[] scriptArgs = event.getScriptEvent().getArguments();
		waveModifierOptions.add((Integer) scriptArgs[2]);
		waveModifierOptions.add((Integer) scriptArgs[3]);
		waveModifierOptions.add((Integer) scriptArgs[4]);
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (!inColosseum || !(event.getActor() instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) event.getActor();
		if (npc.getId() != NpcID.COLOSSEUM_MANTICORE)
		{
			return;
		}

		if (npc.getAnimation() == AnimationID.NPC_MANTICORE_01_TRIPLE_THROW)
		{
			ManticoreState state = manticoresByIndex.computeIfAbsent(npc.getIndex(), i -> new ManticoreState());
			state.attacksRemaining = 3;
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		if (npc != null)
		{
			manticoresByIndex.remove(npc.getIndex());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!inColosseum || manticoresByIndex.isEmpty())
		{
			return;
		}

		Iterator<Map.Entry<Integer, ManticoreState>> iterator = manticoresByIndex.entrySet().iterator();
		while (iterator.hasNext())
		{
			Map.Entry<Integer, ManticoreState> entry = iterator.next();
			NPC npc = findNpcByIndex(entry.getKey());
			if (npc == null || npc.getId() != NpcID.COLOSSEUM_MANTICORE || npc.isDead())
			{
				iterator.remove();
				continue;
			}

			ManticoreState state = entry.getValue();
			if (state.attacksRemaining > 0)
			{
				String special = specialForStyle(state.style);
				if (special != null)
				{
					logSpecial(npc, special);
				}
				state.attacksRemaining--;
				state.style = null;
			}

			updateStyle(npc, state);
		}
	}

	private void updateStyle(NPC npc, ManticoreState state)
	{
		if (state.style != null)
		{
			return;
		}

		int anim = npc.getAnimation();
		if (anim != AnimationID.NPC_MANTICORE_01_TRIPLE_CHARGE
				&& anim != AnimationID.NPC_MANTICORE_01_TRIPLE_THROW)
		{
			return;
		}

		for (ActorSpotAnim spotAnim : npc.getSpotAnims())
		{
			int id = spotAnim.getId();
			if (id == SpotanimID.VFX_MANTICORE_01_PROJECTILE_MAGIC_01)
			{
				state.style = ManticoreStyle.MAGE;
				return;
			}
			if (id == SpotanimID.VFX_MANTICORE_01_PROJECTILE_RANGED_01)
			{
				state.style = ManticoreStyle.RANGE;
				return;
			}
			if (id == SpotanimID.VFX_MANTICORE_01_PROJECTILE_MELEE_01)
			{
				state.style = ManticoreStyle.MELEE;
				return;
			}
		}
	}

	private static String specialForStyle(ManticoreStyle style)
	{
		if (style == null)
		{
			return null;
		}
		switch (style)
		{
			case MAGE:
				return "MANTICORE_MAGE";
			case RANGE:
				return "MANTICORE_RANGE";
			default:
				return "MANTICORE_MELEE";
		}
	}

	private NPC findNpcByIndex(int index)
	{
		for (NPC npc : client.getNpcs())
		{
			if (npc.getIndex() == index)
			{
				return npc;
			}
		}
		return null;
	}

	private void logSpecial(NPC npc, String special)
	{
		String source = npc.getId() + "-" + npc.getIndex();
		logQueueManager.queue(String.format("%s attack special %s", source, special));
	}

	private void logModifierChoice()
	{
		int selectedIndex = client.getVarbitValue(VarbitID.COLOSSEUM_SELECTED_MODIFIER) - 1;
		if (selectedIndex < 0 || selectedIndex >= waveModifierOptions.size())
		{
			waveModifierOptions.clear();
			return;
		}

		int chosenModifier = waveModifierOptions.get(selectedIndex);
		String options = waveModifierOptions.stream()
				.map(String::valueOf)
				.collect(Collectors.joining(","));

		logQueueManager.queue(String.format("COLOSSEUM_MODIFIER\t%d\t%s", chosenModifier, options));

		waveModifierOptions.clear();
	}

	private void reset()
	{
		waveModifierOptions.clear();
		manticoresByIndex.clear();
	}
}

package com.combatlogger.encounters;

import com.combatlogger.LogQueueManager;
import com.combatlogger.model.logs.GameMessageLog;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;

import static com.combatlogger.CombatLoggerPlugin.getCurrentTimestamp;

@Singleton
public class CoxHelper
{
	private static final String RAID_COMPLETE_MESSAGE = "Congratulations - your raid is complete!";

	private final Client client;
	private final LogQueueManager logQueueManager;

	@Inject
	CoxHelper(Client client, LogQueueManager logQueueManager)
	{
		this.client = client;
		this.logQueueManager = logQueueManager;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) != 1)
		{
			return;
		}

		if (event.getType() != ChatMessageType.FRIENDSCHATNOTIFICATION)
		{
			return;
		}

		String message = event.getMessage();
		if (!Text.removeTags(message).startsWith(RAID_COMPLETE_MESSAGE))
		{
			return;
		}

		logQueueManager.queue(new GameMessageLog(
				client.getTickCount(),
				getCurrentTimestamp(),
				message
		));

		int partySize = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE);
		int teamPoints = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSCORE);
		int playerPoints = client.getVarpValue(VarPlayerID.RAIDS_PLAYERSCORE);

		logQueueManager.queue(String.format(
				"COX_RAID_COMPLETE\t%d\t%d\t%d",
				partySize,
				teamPoints,
				playerPoints
		));
	}
}

package com.combatlogger.encounters;

import com.combatlogger.LogQueueManager;
import net.runelite.api.Client;
import net.runelite.api.GraphicsObject;
import net.runelite.api.NPC;
import net.runelite.api.Projectile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GraphicsObjectCreated;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.ProjectileMoved;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/**
 * Doom of Mokhaiotl encounter helpers (slam vs shockwave, orb/ball style projectiles).
 */
@Singleton
public class DoomHelper
{
	private static final Set<Integer> STYLE_PROJECTILES = new HashSet<>(Arrays.asList(
			SpotanimID.VFX_STANDARD_PROJECTILE_MELEE,
			SpotanimID.VFX_STANDARD_PROJECTILE_MAGIC,
			SpotanimID.VFX_STANDARD_PROJECTILE_RANGE,
			SpotanimID.VFX_ROCK_PROJECTILE_LAUNCH_RANGE,
			SpotanimID.VFX_ROCK_PROJECTILE_LAUNCH_MAGIC
	));

	private static final Set<Integer> SHOCKWAVE_GRAPHICS_IDS = new HashSet<>(Arrays.asList(
			SpotanimID.VFX_AREA_SLAM_01,
			SpotanimID.VFX_AREA_SLAM_02,
			SpotanimID.VFX_AREA_SLAM_03
	));

	private static final Set<Integer> MOKHAIOTL_IDS = new HashSet<>(Arrays.asList(
			NpcID.DOM_BOSS,
			NpcID.DOM_BOSS_SHIELDED,
			NpcID.DOM_BOSS_BURROWED
	));

	private final Client client;
	private final LogQueueManager logQueueManager;

	private int mokhaiotlIndex = -1;
	private int mokhaiotlId = -1;
	private int lastCarTick = -1;
	private boolean shockwaveSeenThisTick = false;
	private Integer pendingStyleProjectileId = null;

	@Inject
	DoomHelper(Client client, LogQueueManager logQueueManager)
	{
		this.client = client;
		this.logQueueManager = logQueueManager;
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (npc != null && MOKHAIOTL_IDS.contains(npc.getId()))
		{
			trackMokhaiotl(npc);
		}
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		NPC npc = event.getNpc();
		if (npc == null)
		{
			return;
		}

		if (MOKHAIOTL_IDS.contains(npc.getId()))
		{
			trackMokhaiotl(npc);
		}
		else if (mokhaiotlIndex == npc.getIndex())
		{
			reset();
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		if (npc != null && mokhaiotlIndex == npc.getIndex())
		{
			reset();
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (!(event.getActor() instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) event.getActor();
		if (mokhaiotlIndex != npc.getIndex())
		{
			return;
		}

		if (npc.getAnimation() == AnimationID.DOM_BURROWED_MOVEMENT)
		{
			int tick = client.getTickCount();
			if (lastCarTick <= tick - 5)
			{
				lastCarTick = tick;
			}
		}
	}

	@Subscribe
	public void onProjectileMoved(ProjectileMoved event)
	{
		Projectile projectile = event.getProjectile();
		if (projectile == null || !STYLE_PROJECTILES.contains(projectile.getId()))
		{
			return;
		}

		int elapsed = projectile.getEndCycle() - projectile.getStartCycle() - projectile.getRemainingCycles();
		if (elapsed != 0)
		{
			return;
		}

		NPC mokhaiotl = findTrackedMokhaiotl();
		if (mokhaiotl == null || mokhaiotl.getWorldArea() == null)
		{
			return;
		}

		WorldPoint source = projectile.getSourcePoint();
		if (source != null && mokhaiotl.getWorldArea().contains(source) && pendingStyleProjectileId == null)
		{
			pendingStyleProjectileId = projectile.getId();
		}
	}

	@Subscribe
	public void onGraphicsObjectCreated(GraphicsObjectCreated event)
	{
		GraphicsObject object = event.getGraphicsObject();
		if (object != null && SHOCKWAVE_GRAPHICS_IDS.contains(object.getId()))
		{
			shockwaveSeenThisTick = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (shockwaveSeenThisTick)
		{
			NPC mokhaiotl = findTrackedMokhaiotl();
			if (mokhaiotl != null)
			{
				int tick = client.getTickCount();
				boolean isSlam = mokhaiotl.getId() == NpcID.DOM_BOSS_BURROWED
						|| lastCarTick >= tick - 12;
				logSpecial(mokhaiotl, isSlam ? "SLAM" : "SHOCKWAVE");
			}
		}

		shockwaveSeenThisTick = false;
	}

	/**
	 * First style projectile seen this tick for Mokhaiotl orb/ball anims.
	 */
	public Integer resolveStyleProjectileId()
	{
		if (pendingStyleProjectileId != null)
		{
			return pendingStyleProjectileId;
		}

		NPC mokhaiotl = findTrackedMokhaiotl();
		if (mokhaiotl == null || mokhaiotl.getWorldArea() == null)
		{
			return null;
		}

		for (Projectile projectile : client.getProjectiles())
		{
			if (!STYLE_PROJECTILES.contains(projectile.getId()))
			{
				continue;
			}

			WorldPoint source = projectile.getSourcePoint();
			if (source != null && mokhaiotl.getWorldArea().contains(source))
			{
				return projectile.getId();
			}
		}
		return null;
	}

	public void clearPendingStyleProjectile()
	{
		pendingStyleProjectileId = null;
	}

	public void reset()
	{
		mokhaiotlIndex = -1;
		mokhaiotlId = -1;
		lastCarTick = -1;
		shockwaveSeenThisTick = false;
		pendingStyleProjectileId = null;
	}

	private void trackMokhaiotl(NPC npc)
	{
		mokhaiotlIndex = npc.getIndex();
		mokhaiotlId = npc.getId();
	}

	private NPC findTrackedMokhaiotl()
	{
		if (mokhaiotlIndex < 0)
		{
			return null;
		}

		for (NPC npc : client.getNpcs())
		{
			if (npc.getIndex() == mokhaiotlIndex)
			{
				mokhaiotlId = npc.getId();
				return npc;
			}
		}
		return null;
	}

	private void logSpecial(NPC npc, String special)
	{
		String source = npc.getId() + "-" + npc.getIndex();
		logQueueManager.queue(String.format("%s attack special %s", source, special));
	}
}

package com.combatlogger.encounters;

import com.combatlogger.LogQueueManager;
import com.combatlogger.util.RaidWipeUtil;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Arrays;
import java.util.List;

@Singleton
public class ToaHelper
{
	private static final int NEXUS_REGION = 14160;
	private static final int RAID_LEVEL_LOG_DELAY_TICKS = 5;

	private static final List<Integer> TOA_ORBS_VARBITS = Arrays.asList(
			VarbitID.TOA_CLIENT_P0,
			VarbitID.TOA_CLIENT_P1,
			VarbitID.TOA_CLIENT_P2,
			VarbitID.TOA_CLIENT_P3,
			VarbitID.TOA_CLIENT_P4,
			VarbitID.TOA_CLIENT_P5,
			VarbitID.TOA_CLIENT_P6,
			VarbitID.TOA_CLIENT_P7
	);

	private final Client client;
	private final LogQueueManager logQueueManager;

	private int raidLevelLogTick = -1;

	@Inject
	ToaHelper(Client client, LogQueueManager logQueueManager)
	{
		this.client = client;
		this.logQueueManager = logQueueManager;
	}

	public void onRegionChanged(int regionId)
	{
		// Log invocation level when entering the Nexus at raid start. TOA_CLIENT_RAID_LEVEL is not
		// always populated on the same tick as the region change, so read it 5 ticks later.
		if (regionId == NEXUS_REGION)
		{
			raidLevelLogTick = client.getTickCount() + RAID_LEVEL_LOG_DELAY_TICKS;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (raidLevelLogTick < 0 || client.getTickCount() < raidLevelLogTick)
		{
			return;
		}

		raidLevelLogTick = -1;
		int raidLevel = client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL);
		logQueueManager.queue(String.format("TOA_RAID_LEVEL\t%d", raidLevel));
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getValue() != 30)
		{
			return;
		}

		if (TOA_ORBS_VARBITS.contains(event.getVarbitId()) && RaidWipeUtil.isWipe(client, TOA_ORBS_VARBITS))
		{
			logQueueManager.queue("Tombs of Amascut Wipe");
		}
	}
}

