			AnimationID.NPC_COLOSSI_FINALBOSS_TRIPLEATTACK_SHORTER // Sol Heredit triple parry attack
	));

	public static boolean isNpcAttackAnimation(int animationId)
	{
		return NPC_ATTACK_ANIMATION_IDS.contains(animationId);
	}
}

